-- =========================================================================
-- GANAPATHI MAP - SUPABASE DATABASE SCHEMA & ALL 50 SEED PANDALS
-- Instructions: Copy and paste this script into your Supabase Dashboard:
-- https://supabase.com/dashboard/project/kiawqprxtbicqodmyube/sql/new
-- ==================   =======================================================

-- 1. Create Pandals Table
CREATE TABLE IF NOT EXISTS public.pandals (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    slug TEXT,
    locality TEXT,
    address TEXT,
    latitude NUMERIC(10, 6) NOT NULL,
    longitude NUMERIC(10, 6) NOT NULL,
    establishment_year INT DEFAULT 2025,
    edition TEXT DEFAULT '2025 Edition',
    theme TEXT,
    idol_type TEXT DEFAULT 'Clay Eco Idol',
    is_eco_friendly BOOLEAN DEFAULT true,
    is_featured BOOLEAN DEFAULT false,
    is_trending BOOLEAN DEFAULT false,
    status TEXT DEFAULT 'verified',
    darshan_timings TEXT DEFAULT '06:00 AM - 10:00 PM',
    aarti_timings TEXT DEFAULT '08:00 AM & 07:30 PM',
    annadanam JSONB DEFAULT '{"available": false}'::jsonb,
    facilities JSONB DEFAULT '{"parking": true, "toilets": true, "drinkingWater": true, "accessibility": true, "firstAid": true}'::jsonb,
    crowd_level TEXT DEFAULT 'Moderate',
    cover_image TEXT,
    images JSONB DEFAULT '[]'::jsonb,
    description TEXT,
    uploader_ip TEXT,
    likes_count INT DEFAULT 1,
    checkins_count INT DEFAULT 1,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
);

-- 2. Enable Row Level Security (RLS) & Grant Public Access
ALTER TABLE public.pandals ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Public Read Access" ON public.pandals;
CREATE POLICY "Public Read Access" ON public.pandals FOR SELECT USING (true);

DROP POLICY IF EXISTS "Public Insert Access" ON public.pandals;
CREATE POLICY "Public Insert Access" ON public.pandals FOR INSERT WITH CHECK (true);

DROP POLICY IF EXISTS "Public Delete Access" ON public.pandals;
CREATE POLICY "Public Delete Access" ON public.pandals FOR DELETE USING (true);

